mapper.select:
SELECT id FROM w16_match_ticket
WHERE pool=#{pool} AND state='WAITING' AND expires_at > #{now}
ORDER BY expires_at, id LIMIT #{limit}

mapper.update:
UPDATE w16_rendezvous_meeting
SET expires_at=#{expiresAt}, first_confirmed_at=#{firstConfirmedAt,jdbcType=BIGINT},
    second_confirmed_at=#{secondConfirmedAt,jdbcType=BIGINT}, team_id=#{teamId,jdbcType=BIGINT}, state=#{state}
WHERE match_id=#{matchId} AND challenge_id=#{challengeId} AND idempotency_key=#{matchId}
  AND activity_id=#{activityId} AND issued_at=#{issuedAt}
  AND (first_confirmed_at IS NULL OR first_confirmed_at=#{firstConfirmedAt,jdbcType=BIGINT})
  AND (second_confirmed_at IS NULL OR second_confirmed_at=#{secondConfirmedAt,jdbcType=BIGINT})
  AND (team_id IS NULL OR team_id=#{teamId,jdbcType=BIGINT})
